import{_ as t,o as s,c as a,a6 as i}from"./chunks/framework.CCKCzdWs.js";const n="/diagrams/moving-parts.svg",r="/screenshots/home-empty-connect-waiting.png",o="/screenshots/home-empty-connect-reporting.png",m=JSON.parse('{"title":"Getting started","description":"Piwi Dashboard is a self-hosted server plus a Playwright reporter that keeps every test run. Run the dashboard, connect your suite with one command, and open your first run in three steps.","frontmatter":{"title":"Getting started","description":"Piwi Dashboard is a self-hosted server plus a Playwright reporter that keeps every test run. Run the dashboard, connect your suite with one command, and open your first run in three steps.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/guide/getting-started.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/guide/getting-started.html"}],["meta",{"property":"og:title","content":"Getting started | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Piwi Dashboard is a self-hosted server plus a Playwright reporter that keeps every test run. Run the dashboard, connect your suite with one command, and open your first run in three steps."}]]},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1793450333000}'),h={name:"guide/getting-started.md"};function p(l,e,d,c,u,k){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Piwi is a <strong>server plus a Playwright reporter</strong>. The reporter runs inside <code>npx playwright test</code> and sends the results to the server, which keeps every run with its traces and renders the dashboard. Three steps set up both. New to the vocabulary (<em>run</em>, <em>test case</em>, <em>execution</em>, <em>cluster</em>)? <a href="./concepts.html">Core concepts</a> defines each term the dashboard uses.</p><figure><img src="'+n+`" alt="The reporter, inside a Playwright run on your machine or in CI, streams results and uploads traces to the Piwi server, which keeps them in its database and artifact storage and serves the dashboard to your browser"><figcaption>The same reporter runs locally and in CI; one server keeps every run.</figcaption></figure><h2 id="_1-run-the-dashboard" tabindex="-1">1. Run the dashboard <a class="header-anchor" href="#_1-run-the-dashboard" aria-label="Permalink to &quot;1. Run the dashboard&quot;">​</a></h2><p>The dashboard is one Node process. Pick the way to run it that fits:</p><table tabindex="0"><thead><tr><th>Path</th><th>Best for</th><th>Needs</th></tr></thead><tbody><tr><td><a href="/features/desktop.html">Desktop app</a></td><td>One developer running Playwright locally</td><td>Nothing; the runtime is bundled. Windows x64, Apple-silicon macOS and Linux x86-64; the installers are not signed yet</td></tr><tr><td>Docker <em>(below)</em></td><td>A shared instance for a team, or anything long-lived</td><td>Docker; about 300 MB RAM, 1 vCPU, <code>linux/amd64</code> or <code>linux/arm64</code></td></tr><tr><td><a href="/operate/deployment.html#npm-npx-quick-local-run"><code>npx @piwitests/server</code></a></td><td>A quick local run</td><td>Node.js 22 or later</td></tr><tr><td><a href="/operate/deployment.html#one-click-deploy">One-click deploy</a></td><td>A shared instance with no server of your own</td><td>An account on the host</td></tr></tbody></table><p>With Docker:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-wK-ub" id="tab-pecE2nU" checked><label data-title="Linux / macOS" for="tab-pecE2nU">Linux / macOS</label><input type="radio" name="group-wK-ub" id="tab-dJ6QeK-"><label data-title="Windows (PowerShell)" for="tab-dJ6QeK-">Windows (PowerShell)</label></div><div class="blocks"><div class="language-sh vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phenx/piwitests-server:latest</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1001:1001</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .data</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # the container runs as non-root UID 1001</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Reachable from this machine only: with authentication off, anyone who reaches the port is an administrator.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Publish it on every interface (-p 3000:3000) only once authentication is on.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:3000:3000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pwd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.data:/app/.data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phenx/piwitests-server:latest</span></span></code></pre></div><div class="language-ps1 vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ps1</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker pull phenx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">piwitests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server:latest</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Reachable from this machine only: with authentication off, anyone who reaches the port is an administrator.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Publish it on every interface (-p 3000:3000) only once authentication is on.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">127.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3000</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">v \${PWD}</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.data:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.data phenx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">piwitests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server:latest</span></span></code></pre></div></div></div><p>The dashboard answers at <code>http://localhost:3000</code>. On Linux hosts the container runs as the non-root UID 1001, which is why the snippet creates <code>.data</code> with the right owner; see <a href="/operate/deployment.html#permission-issues-with-volumes">Permission issues with volumes</a> if the container cannot write to it. <a href="/operate/deployment.html">Deployment</a> covers Docker Compose, PostgreSQL and Kubernetes.</p><p>With the desktop app, keep it running: a reporter with no server configured finds it by itself. Its URL and access token, for when you need them, are on its <strong>Setup</strong> page under <strong>Send results to this app</strong>.</p><p>Your test project is unaffected by these requirements: Node 22 is the dashboard&#39;s requirement, not your suite&#39;s. Want to look around first? The <a href="https://piwitests.dev/demo/" target="_blank" rel="noreferrer">live demo</a> runs in your browser on seeded data.</p><h2 id="_2-connect-your-suite" tabindex="-1">2. Connect your suite <a class="header-anchor" href="#_2-connect-your-suite" aria-label="Permalink to &quot;2. Connect your suite&quot;">​</a></h2><p>The dashboard&#39;s connect wizard, on <strong>Home</strong> while it has no project and on <strong>Setup</strong> after, builds every snippet below from your project name and its own URL, and offers three ways to the same setup: one command, a prompt for a coding agent, or the steps by hand. Each ends in <a href="./reporter.html#installing-via-wrapconfig"><code>wrapConfig</code></a> around your config and the <a href="./capture-fixtures.html">capture fixtures</a> in your specs: the reporter entry alone keeps your runs, and those two add the failure screenshots and traces, the network and console capture, and locator healing.</p><figure><img src="`+r+`" alt="The connect wizard on an instance with no project: the project name, the three ways to connect (one command, coding agent, by hand) with the init command, the fixtures import and the test command, and a status line waiting for the first run"><figcaption>The connect wizard, waiting for the first run.</figcaption></figure><h3 id="fast-path-one-command" tabindex="-1">Fast path: one command <a class="header-anchor" href="#fast-path-one-command" aria-label="Permalink to &quot;Fast path: one command&quot;">​</a></h3><p>From your Playwright project, one command installs the reporter, wraps your <code>playwright.config</code>, creates the <a href="./capture-fixtures.html">capture fixtures</a> file and records the connection in <code>.env.example</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --server-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:3000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-project</span></span></code></pre></div><p>It prints one line per step, <code>+</code> for a file it created, <code>~</code> for one it changed, <code>=</code> for one already set, <code>!</code> for a step left to you:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Piwi setup for &quot;my-project&quot;:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ~ [updated] dependency — Installed @piwitests/reporter</span></span>
<span class="line"><span>  ~ [updated] config playwright.config.ts — Wrapped defineConfig(...) with wrapConfig(...) and added the import</span></span>
<span class="line"><span>  + [created] fixtures tests/fixtures.ts — Created capture fixtures — import \`test\` from here in your specs</span></span>
<span class="line"><span>  ~ [updated] env .env.example — Recorded PIWI_DASHBOARD_URL, PIWI_API_KEY</span></span>
<span class="line"><span>  + [created] skill:investigate-failure .claude/skills/investigate-failure/SKILL.md — installed skill</span></span>
<span class="line"><span>  + [created] skill:apply-locator-healing .claude/skills/apply-locator-healing/SKILL.md — installed skill</span></span>
<span class="line"><span>  + [created] skill:stabilize-flaky-tests .claude/skills/stabilize-flaky-tests/SKILL.md — installed skill</span></span>
<span class="line"><span>  + [created] skill:run-the-right-tests .claude/skills/run-the-right-tests/SKILL.md — installed skill</span></span>
<span class="line"><span>  + [created] skill:write-the-missing-test .claude/skills/write-the-missing-test/SKILL.md — installed skill</span></span>
<span class="line"><span>  + [created] skill:fix-a-reported-bug .claude/skills/fix-a-reported-bug/SKILL.md — installed skill</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Next:</span></span>
<span class="line"><span>  • If your dashboard has authentication on, create an API key (Settings → Account → API keys) and put it in .env as PIWI_API_KEY: the reporter reads it from the .env next to your Playwright config. Keep .env out of git; in CI, set PIWI_API_KEY as a secret.</span></span>
<span class="line"><span>  • In your specs, import \`test\` (and \`expect\`) from your fixtures file instead of \`@playwright/test\`.</span></span>
<span class="line"><span>  • Run \`npx playwright test\` — the run should appear at http://localhost:3000.</span></span>
<span class="line"><span>  • For a machine-readable check, set PIWI_OUTPUT_FILE=piwi-run.json and read runUrl from that file after the run.</span></span></code></pre></div><p>Every step is idempotent, so it is safe to re-run. When <code>init</code> finds a config shape it will not rewrite, or a fixtures file that already exists, it reports that step as <code>manual</code> with the exact change to make instead of touching the file. Pass <code>--dry-run</code> to preview, or <code>--json</code> for a machine-readable plan that a coding agent can follow to finish the manual steps. <code>init</code> also adds the <a href="/features/agent-skills.html">Piwi agent skills</a> to the project. See <code>npx @piwitests/reporter init --help</code> for all options.</p><blockquote><p>The package is <code>@piwitests/reporter</code> and its command is <code>piwi</code>. Invoke it through the package name, <code>npx @piwitests/reporter &lt;command&gt;</code>, so npx resolves this package: <code>npx piwi</code> would fetch an unrelated <code>piwi</code> package from npm. Once the reporter is a dependency of your project, <code>npx piwi &lt;command&gt;</code> works too.</p></blockquote><p>Then import <code>test</code> from the fixtures file in your specs, the one change <code>init</code> leaves to you:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { test, expect } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;./fixtures&#39;</span></span></code></pre></div><p>A coding agent can do both: the <strong>Coding agent</strong> path on <strong>Setup</strong> gives it a prompt that runs <code>init --json</code>, finishes the steps it reports as <code>manual</code> and moves the specs onto the fixtures.</p><p>If authentication is on, pass an <a href="/operate/api-keys.html">API key</a> as <code>PIWI_API_KEY</code>; <strong>Setup</strong> creates one in place. When developers run the <a href="/features/desktop.html">desktop app</a> and CI reports to a shared dashboard, add <code>--desktop-app prefer</code>: <a href="./reporter.html#local-runs-to-the-desktop-app-ci-to-a-team-server">local runs then land in the app</a>. To wire the reporter in by hand, or to send one run without editing your config, see <a href="./reporter.html">Reporter</a>.</p><h2 id="_3-run-your-tests" tabindex="-1">3. Run your tests <a class="header-anchor" href="#_3-run-your-tests" aria-label="Permalink to &quot;3. Run your tests&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>The run streams into the dashboard while it executes, and the reporter prints a <code>View run:</code> link at the end. Open it.</p><p>While it runs, the wizard&#39;s status line changes from <em>Waiting for the first run</em> to the run reporting, with a link to watch it:</p><figure><img src="`+o+'" alt="The wizard&#39;s status line: a run of checkout is reporting now, with a Watch it link"><figcaption>The checkpoint: your first run is reporting.</figcaption></figure><p>If nothing shows up, read the first lines the reporter prints. This one means it found no server to report to:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Piwi Dashboard] Not enabled — set PIWI_DASHBOARD_URL or serverUrl to enable.</span></span></code></pre></div><p>Set <code>PIWI_DASHBOARD_URL</code>, in the environment or the <code>.env</code> next to your Playwright config, or rerun <code>init</code> with <code>--server-url</code>. From WSL, a dev container or another machine, the URL is the dashboard&#39;s address as that machine reaches it, not <code>localhost</code>.</p><p>The home page and a project&#39;s page leave out partial runs (a run of a few files) until you change their <strong>Filters</strong>, and a project&#39;s page leaves out branches other than the default one too. The <strong>Filters</strong> block counts the runs it hides, with <strong>Include partial runs</strong> and <strong>Show all branches</strong> to bring them back.</p><p>In CI nothing Piwi-specific is needed: the same reporter runs inside <code>npx playwright test</code>, pointed at your instance with <code>PIWI_DASHBOARD_URL</code> and <code>PIWI_API_KEY</code>. <a href="./ci.html">CI &amp; sharding</a> has the pipeline examples.</p><h2 id="your-first-failure" tabindex="-1">Your first failure <a class="header-anchor" href="#your-first-failure" aria-label="Permalink to &quot;Your first failure&quot;">​</a></h2><p>When a test fails, its execution page opens on what happened, the most likely cause and the next step, with the trace, screenshots and logs underneath. <a href="./first-failure.html">Your first failure, explained</a> walks through one failing test from its headline to its evidence.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./concepts.html">Core concepts</a>: the vocabulary the dashboard and these docs use</li><li><a href="./reporter.html">Reporter</a>: manual setup, options, streaming and authentication</li><li><a href="./capture-fixtures.html">Capture fixtures</a>: what the fixtures file adds</li><li><a href="/operate/capabilities.html">Choose what you use</a>: turn off the capabilities you do not need</li><li><a href="/operate/deployment.html">Deployment</a>: running the dashboard for a team</li></ul>',39)])])}const y=t(h,[["render",p]]);export{m as __pageData,y as default};
